package ru.epocharmory.client;

import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import ru.epocharmory.*;

public final class CodexScreen extends Screen {
    private int page;
    private final List<String[]> pages=new ArrayList<>();
    public static void open(){Minecraft.getInstance().setScreen(new CodexScreen());}
    public CodexScreen(){
        super(Component.literal("Кодекс кузнеца"));
        pages.add(new String[]{"Кузница эпох","Открой станок ПКМ. Слева — поиск по результату или ингредиенту. Выбери рецепт и наведи мышь: увидишь точный расход. Призрачные иконки показывают раскладку.\n\n«Вложить» переносит материалы из инвентаря, если шесть входных ячеек пусты. Инструмент — в отдельный слот. Топливо — под ним.\n\nНа ручном станке нажимай «Работать». Автоматические печи работают сами. Забирай и основной результат, и побочный продукт: заполненный выход останавливает работу.\n\nНачало: книга + железный самородок → кодекс. Затем молот, горн, наковальня и верстак оружейника."});
        pages.add(new String[]{"Металлы и руда","Олово, боксит, рутил и доломит встречаются в новых чанках Верхнего мира. Руды имеют обычную и глубинную разновидности; с ними работают удача и шёлковое касание.\n\nБронза: 3 меди + 1 олова → 4 слитка. Сталь: железо + древесный уголь + флюс в тигельной печи.\n\nСыродутная печь даёт крицу и шлак; оббей крицу молотом на наковальне. Это выгодная, но более долгая альтернатива обычной плавке железа.\n\nФлюс получают из кальцита. Золото мягкое: слабее и менее долговечно, зато хорошо зачаровывается."});
        pages.add(new String[]{"От слитка до клинка","Горн нагревает слиток до заготовки. На наковальне молот формует короткий или длинный клинок, головку оружия либо пластину.\n\nГорячий металл остаётся пригодным к ковке и закалке 3 игровых минуты, даже в сундуке. Остывшая вещь сохраняется: верни её в горн для нагрева.\n\nВанна охлаждает деталь: требуется ведро воды, пустое ведро выходит отдельно. Для стали и дамаска затем нужен отпуск при 250–450 °C.\n\nТочильный станок завершает детали. Рукояти, ремни и крепления добавляются только после обработки металла."});
        pages.add(new String[]{"Дамаск и катана","Для сварного дамаска кузнец соединяет железо и сталь с флюсом. Сначала создай пакет в горне, затем прокуй его на наковальне: так получишь дамасские слитки.\n\nЭто игровая версия сварного узорчатого металла, а не точная реконструкция тигельного вутца.\n\nСтальную и дамасскую катану собирают из длинного клинка с дифференциальной закалкой: горячая деталь + глиняная обмазка + вода. Остальные клинки проходят обычное охлаждение.\n\nПроценты, температуры неферросплавов и длительности упрощены для игры."});
        pages.add(new String[]{"Четыре вида доспехов","Кольчуга: волочение проволоки → кольца → клёпка кольчужных полотен → подкладка и сборка. Хороша против рубящих ударов, слабее против дробящих.\n\nЛамелляр: небольшие пластины соединяются ремешками. Даёт дополнительную защиту от снарядов.\n\nБригантина: малые пластины приклёпаны к тканевой основе. Универсальная защита при умеренном весе.\n\nЛаты: горячая формовка крупных пластин, охлаждение, обработка, клёпка, ремни и мягкая подкладка. Самая дорогая конструкция. Каждый надетый предмет даёт свою долю эффектов."});
        pages.add(new String[]{"Поздние сплавы","Электролизёр питается красной пылью в топливном слоте. Это условная поздняя промышленная ветка, а не средневековый аппарат.\n\nБоксит → глинозём → алюминий. Доломит → магнезия → магниевый сплав. Рутил → титановая губка → титановый сплав. Во всех случаях требуются дополнительные реагенты.\n\nАлюминиевый и магниевый сплавы легче, но хуже держат удар. Титан прочен и лёгок, зато дорог в производстве.\n\nАлмазное оружие имеет металлическую основу и алмазную кромку; незерит добавляется к дамасской основе. Это фантастическое продолжение кузницы Minecraft."});
        pages.add(new String[]{"Оружие и бой","Молот, булава и моргенштерн снижают действие брони. Пробитие означает долю игнорируемого снижения урона от брони, а не долю здоровья. Зачарования и зелья защиты продолжают работать.\n\nКопьё и пика бьют дальше и получают +30% урона по приближающейся цели. Кинжал и катар наносят +50% при ударе сзади. Топор и алебарда отключают щиты. Кистень частично обходит блок.\n\nДля двуручного оружия освободи вторую руку: иначе −25% урона, −15% скорости атаки и нельзя блокировать щитом.\n\nВсплывающие подсказки показывают дальность и особенности каждого вида."});
        pages.add(new String[]{"Щиты и парирование","ПКМ поднимает щит. После стандартной задержки Minecraft короткое окно парирования полностью отражает обычный удар и ненадолго мешает атакующему. Кистень всё равно пробивает часть блока.\n\nСтойкость: 100. Удары тратят её в зависимости от щита, массы материала и силы атаки. После паузы она восстанавливается, если предмет не используется.\n\nПри нехватке стойкости блок срывается и щит уходит на перезарядку на 2 секунды. Полоска над хотбаром показывает остаток.\n\nЩиты сохраняют обычное направление блока: спина не защищена. Форма влияет на долю поглощённого урона, а не на размер хитбокса."});
        for(int group=0;group<2;group++){
            var text=new StringBuilder();for(int i=group*5;i<group*5+5;i++){var s=ShieldKind.values()[i];text.append(s.russian).append(": ближний бой ").append(Math.round(s.melee*100)).append("%, снаряды ").append(Math.round(s.projectile*100)).append("%, базовая стойкость ").append(s.stamina).append(".\n\n");}
            pages.add(new String[]{"Десять щитов · "+(group+1),text.toString()});
        }
        pages.add(new String[]{"Источники и мир","Основы конструкций: The Metropolitan Museum of Art — The Function of Armor in Medieval and Renaissance Europe; A. R. Williams — On the Manufacture of Armor in Fifteenth-Century Italy.\n\nКольца и клёпка: Martijn A. Wijnhoven, European Mail Armour, глава 8. Ламелляр и сварные клинки: Royal Armouries. Катаны: The Japanese Blade — Technology and Manufacture, The Met.\n\nПолные ссылки, различия истории и игровой условности, таблицы баланса и список рецептов находятся в README_RU.md, HISTORY_RU.md и CRAFTS_RU.md в архиве исходников.\n\nМод работает и в одиночной игре, и на сервере; станки хранят общий инвентарь."});
    }
    @Override protected void init(){
        int x=(width-350)/2,y=(height-280)/2;
        addRenderableWidget(Button.builder(Component.literal("←"),b->page=Math.max(0,page-1)).bounds(x+14,y+252,40,18).build());
        addRenderableWidget(Button.builder(Component.literal("→"),b->page=Math.min(pages.size()-1,page+1)).bounds(x+296,y+252,40,18).build());
        addRenderableWidget(Button.builder(Component.literal("Закрыть"),b->onClose()).bounds(x+132,y+252,86,18).build());
    }
    @Override public void renderBackground(GuiGraphics g,int mx,int my,float delta){
        super.renderBackground(g,mx,my,delta);int x=(width-350)/2,y=(height-280)/2;
        g.fill(x-2,y-2,x+352,y+282,0xFF72573D);g.fill(x,y,x+350,y+280,0xFFE1D4B6);
        g.drawString(font,pages.get(page)[0],x+16,y+15,0xFF3D3027,false);
        g.fill(x+16,y+29,x+334,y+30,0xFFB39B72);
        g.drawWordWrap(font,Component.literal(pages.get(page)[1]),x+16,y+40,318,0xFF3A342E);
        g.drawCenteredString(font,(page+1)+" / "+pages.size(),x+175,y+238,0xFF77654D);
    }
    @Override public boolean isPauseScreen(){return false;}
}
